INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q68475', 'Bolivian War of Independence', 'The Bolivian War of Independence (Spanish: Guerra de Independencia de Bolivia, 1809–1825) began with the establishment of government juntas in Sucre and La Paz after the Chuquisaca Revolution and La Paz revolution. These Juntas, part of the Viceroyalty of the Río de la Plata, were defeated shortly after by Peruvian royalist forces.', 1809, 5, 25, 1825, NULL, NULL, 'day', '25 May 1809 – 1825', 56, 'https://en.wikipedia.org/wiki/Bolivian_War_of_Independence'),
  ('Q5116509', 'Chuquisaca Revolution', 'The Chuquisaca Revolution was a popular uprising on 25 May 1809 against Ramón García de León y Pizarro, Governor-intendant of the Intendancy of Chuquisaca (or Charcas) (today Sucre, Bolivia). The Real Audiencia of Charcas, with support from the faculty of University of Saint Francis Xavier, deposed the governor and formed a junta.', 1809, 5, 25, NULL, NULL, NULL, 'day', '25 May 1809', 41, 'https://en.wikipedia.org/wiki/Chuquisaca_Revolution'),
  ('Q6464343', 'La Paz Revolution', 'The City of La Paz is located in the highlands of Upper Peru, located in what is known today as Bolivia. This area became the center of a political upheaval in 1809.', 1809, NULL, NULL, NULL, NULL, NULL, 'year', '1809', 39, 'https://en.wikipedia.org/wiki/La_Paz_revolution'),
  ('Q2890073', 'Battle of Suipacha', 'The Battle of Suipacha was fought on 7 November 1810 in Bolivia during the Bolivian War of Independence between the Spanish colonial army and the Republican forces sent by the Primera Junta from Buenos Aires. At the time, Bolivia was known as Upper Peru.', 1810, 11, 7, NULL, NULL, NULL, 'day', '7 November 1810', 41, 'https://en.wikipedia.org/wiki/Battle_of_Suipacha'),
  ('Q4872673', 'Battle of Vilcapugiou', 'The Battle of Vilcapugio (Quechua: Sacred Well) was a major battle fought on October 1, 1813, during the second Campaign of Upper Peru in the Argentine War of Independence, where the United Provinces forces led by General Manuel Belgrano were defeated by a royalist army, led by Joaquin de la Pezuela.', 1813, 10, 1, NULL, NULL, NULL, 'day', '1 October 1813', 34, 'https://en.wikipedia.org/wiki/Battle_of_Vilcapugio'),
  ('Q2918225', 'Bolivian Declaration of Independence', 'Bolivia''s independence was definitively proclaimed on 6 August 1825 at a congress held in Chuquisaca.', 1825, 8, 6, NULL, NULL, NULL, 'day', '6 August 1825', 41, 'https://en.wikipedia.org/wiki/Bolivian_Declaration_of_Independence'),
  ('Q6151969', 'Treaty of Piquiza', 'The Peruvian–Bolivian War of 1828, First Peruvian invasion of Bolivia or First Peruvian intervention in Bolivia was an invasion of Bolivia by Peru headed by Agustín Gamarra in the form of a foreign intervention in an internal conflict in the Republic of Bolivia, being the first important war in the new country, just three years after becoming independent, and endangering its autonomy as a result of the occupation. Its objective was to force the departure of the troops of the Republic of Colombia from Bolivia, the resignation of Antonio José de Sucre, and the prevention of the opening of a…', 1828, 7, 6, NULL, NULL, NULL, 'day', '6 July 1828', 30, 'https://en.wikipedia.org/wiki/Treaty_of_Piquiza'),
  ('Q28131511', 'Peruvian Pacification War', 'The Bolivian occupation of Peru, known in Bolivia as the Pacification of Peru (Spanish: Pacificación del Perú), took place during the civil war between Andrés de Santa Cruz and Felipe Santiago Salaverry. The allied Bolivian–Peruvian Army led by Santa Cruz, with the support of militias from Iquicha led by Antonio Huachaca successfully fought the allied forces of Salaverry and Agustín Gamarra, achieving its goal of establishing a Confederate state consisting of a Peruvian and Bolivian state.', 1835, NULL, NULL, 1836, NULL, NULL, 'year', '1835–1836', 26, 'https://en.wikipedia.org/wiki/Bolivian_occupation_of_Peru'),
  ('Q495202', 'Guerra de la Union y la Fuerza', 'The Peruvian–Bolivian War was a warlike confrontation between Peru and Bolivia in the years 1841 and 1842. In 1841, Agustín Gamarra, President of Peru, tried to annex Bolivia, which cost the Peruvian president his life on November 18, 1841 at the Battle of Ingavi.', 1841, 10, 1, 1842, 6, 7, 'day', '1 October 1841 – 7 June 1842', 41, 'https://en.wikipedia.org/wiki/Peruvian%E2%80%93Bolivian_War_of_1841%E2%80%9342'),
  ('Q1782533', 'Battle of Ingavi', 'The Battle of Ingavi was fought on 18 November 1841, near Viacha, during the Peruvian–Bolivian War of 1841–1842. The Bolivian Army under the command of José Ballivián repelled the invading Peruvian Army commanded by Agustín Gamarra, who was killed in action.', 1841, 11, 18, NULL, NULL, NULL, 'day', '18 November 1841', 39, 'https://en.wikipedia.org/wiki/Battle_of_Ingavi'),
  ('Q49202540', 'Tratado de Puno', 'The Peruvian–Bolivian War was a warlike confrontation between Peru and Bolivia in the years 1841 and 1842. In 1841, Agustín Gamarra, President of Peru, tried to annex Bolivia, which cost the Peruvian president his life on November 18, 1841 at the Battle of Ingavi.', 1842, 6, 7, NULL, NULL, NULL, 'day', '7 June 1842', 34, 'https://en.wikipedia.org/wiki/Treaty_of_Puno'),
  ('Q742813', 'Chincha Islands War', 'The Chincha Islands War, also known as Spanish–South American War (Spanish: Guerra hispano-sudamericana), was a series of coastal and naval battles between Spain and its former colonies of Peru, Chile, Ecuador, and Bolivia from 1865 to 1879. The conflict began with Spain''s seizure of the guano-rich Chincha Islands in one of a series of attempts by Spain, under Isabella II, to reassert its influence over its former South American colonies.', 1864, 4, 14, 1866, NULL, NULL, 'day', '14 April 1864 – 1866', 61, 'https://en.wikipedia.org/wiki/Chincha_Islands_War'),
  ('Q152004', 'War of the Pacific', 'The War of the Pacific (Spanish: Guerra del Pacífico), also known by multiple other names, was a war between Chile and a Bolivian–Peruvian alliance from 1879 to 1884. Fought over Chilean claims on coastal Bolivian territory in the Atacama Desert, the war ended with victory for Chile, which gained a significant amount of resource-rich territory from Peru and Bolivia.', 1879, 4, 5, 1884, 4, 4, 'day', '5 April 1879 – 4 April 1884', 79, 'https://en.wikipedia.org/wiki/War_of_the_Pacific'),
  ('Q3320910', 'Battle of Topeter', 'The Battle of Topáter, or Battle of Calama, was fought on March 23, 1879, between Chile and Bolivia. It was the first battle of the War of the Pacific.', 1879, 3, 23, NULL, NULL, NULL, 'day', '23 March 1879', 39, 'https://en.wikipedia.org/wiki/Battle_of_Top%C3%A1ter'),
  ('Q5804048', 'Chilean occupation of Antofagasta', 'The War of the Pacific (Spanish: Guerra del Pacífico), also known by multiple other names, was a war between Chile and a Bolivian–Peruvian alliance from 1879 to 1884. Fought over Chilean claims on coastal Bolivian territory in the Atacama Desert, the war ended with victory for Chile, which gained a significant amount of resource-rich territory from Peru and Bolivia.', 1879, 2, 14, NULL, NULL, NULL, 'day', '14 February 1879', 26, 'https://en.wikipedia.org/wiki/Chilean_occupation_of_Antofagasta'),
  ('Q18014904', 'Battle of Tacna', 'The Battle of Tacna, also known as the Battle of the Alto de la Alianza, was a battle that took place on May 26, 1880, at the plateau of the Alto de la Alianza, a hill a few miles north of the Peruvian city of Tacna. It effectively destroyed the Peru-Bolivian alliance against Chile, forged by a secret treaty signed in 1873.', 1880, 5, 26, NULL, NULL, NULL, 'day', '26 May 1880', 47, 'https://en.wikipedia.org/wiki/Battle_of_Tacna'),
  ('Q2606574', 'Acre War', 'The Acre War, known in Brazil as Acrean Revolution (Portuguese: Revolução Acreana) and in Spanish as Guerra del Acre ("War of the Acre") was a border conflict between Bolivia and the First Brazilian Republic over the Acre Region, which was rich in rubber and gold deposits. The conflict had two phases between 1899 and 1903, and ended with an Acrean victory and the subsequent Treaty of Petrópolis, which ceded Acre to Brazil.', 1899, NULL, NULL, 1903, NULL, NULL, 'year', '1899–1903', 56, 'https://en.wikipedia.org/wiki/Acre_War'),
  ('Q5887712', 'Bolivian Civil War', 'The Bolivian Civil War, also known as the Federal War (Spanish: Guerra Federal) was a civil war in Bolivia fought from 1898 to 1899. The war saw two factions, a conservative side supported by the political, economic and religious elite of the country with control of the armed forces and who defended a unitary state, and a liberal faction opposed to the policies set by the state and that intended to transform the country into a federation, with support of the peasantry, the indigenous peoples and small Catholic businesses.', 1899, NULL, NULL, 1899, 4, 10, 'year', '1899', 30, 'https://en.wikipedia.org/wiki/Bolivian_Civil_War'),
  ('Q1122547', 'Treaty of Petrópolis', 'The Treaty of Petrópolis, signed on November 17, 1903, in the Brazilian city of Petrópolis, ended the Acre War between Bolivia and Brazil over the then-Bolivian territory of Acre (today the Acre state), a desirable territory in Bolivia-Brazil border during the contemporary rubber boom. The treaty, drafted by Brazilian foreign affairs minister José Maria da Silva Paranhos, gave Brazil the territory of Acre (191,000 km2), in exchange for over 3,000 km2 of Brazilian territory between the Abuna River and Madeira River, a monetary payment of two million British pounds, paid in two installments,…', 1903, 11, 11, NULL, NULL, NULL, 'day', '11 November 1903', 57, 'https://en.wikipedia.org/wiki/Treaty_of_Petr%C3%B3polis'),
  ('Q473661', 'Treaty of Peace and love', 'The Treaty of Peace and Friendship of 1904 between Chile and Bolivia was signed in Santiago de Chile on 20 October 1904, to delineate the boundary through 96 specified points between Cerro Zapaleri and Cerro Chipe and to regulate the relations between the two countries 20 years after the end of the War of the Pacific. The Bolivia–Chile boundary is about 861 kilometres (535 mi) long and is demarcated by pillars in the Andes.', 1904, 10, 20, NULL, NULL, NULL, 'day', '20 October 1904', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Peace_and_Friendship_(1904)'),
  ('Q28220486', '1920 Bolivian coup d''état', '1920 Bolivian coup d''état was a bloodless takeover of power in Bolivia by the Republican party on July 12, 1920 which overthrew the previously ruling government of the Liberal Party and brought Bautista Saavedra to power as President from 1920 until 1925. Republicans were less united by a single ideology than a wide alliance of former Liberals and some Conservative elites who usually had some personal conflicts with the ruling Liberals and wanted to gain power for themselves.', 1920, 7, 12, NULL, NULL, NULL, 'day', '12 July 1920', 30, 'https://en.wikipedia.org/wiki/1920_Bolivian_coup_d''%C3%A9tat'),
  ('Q2990714', 'Treaty of Lima', 'The Treaty of Lima was a boundary treaty signed on June 3, 1929. The agreement put an end to the territorial dispute regarding the provinces of Tacna and Arica, which had been administered by Chile since 1883.', 1929, 6, 3, NULL, NULL, NULL, 'day', '3 June 1929', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Lima_(1929)'),
  ('Q223126', 'Chaco War', 'The Chaco War (Spanish: Guerra del Chaco, Guarani: Cháko Ñorairõ) was fought from 1932 to 1935. It was between Bolivia and Paraguay over control of the northern part of the Gran Chaco region (known in Spanish as the Chaco Boreal), which was thought to be rich in petroleum.', 1932, 9, 9, 1935, 6, 12, 'day', '9 September 1932 – 12 June 1935', 74, 'https://en.wikipedia.org/wiki/Chaco_War'),
  ('Q108830836', '1934 Bolivian coup d''état', 'The 1934 Bolivian coup d''état, colloquially known as the Corralito of Villamontes (Spanish: Corralito de Villamontes), was a military coup in Bolivia that deposed President Daniel Salamanca in the midst of the Chaco War. Two days before the coup, Salamanca and his presidential delegation arrived at the military headquarters in Villamontes with the intent of removing General Enrique Peñaranda as commander-in-chief of the armed forces and replacing him with General José Leonardo Lanza.', 1934, 11, 27, NULL, NULL, NULL, 'day', '27 November 1934', 26, 'https://en.wikipedia.org/wiki/1934_Bolivian_coup_d''%C3%A9tat'),
  ('Q75720321', '1936 Bolivian coup d''état', 'The 1936 Bolivian coup d''état, also known as the Socialist Revolution of 1936, was a civil-military coup in Bolivia that deposed President José Luis Tejada Sorzano, bringing an end to traditional political order and bringing forward the period of Military Socialism in the country. On 17 May 1936, following the largest strike movement known until then in Bolivia, the military under the young lieutenant colonel Germán Busch overthrew the government of Tejada.', 1936, 5, NULL, NULL, NULL, NULL, 'month', 'May 1936', 30, 'https://en.wikipedia.org/wiki/1936_Bolivian_coup_d''%C3%A9tat'),
  ('Q5051592', 'Catavi Massacre', 'The Catavi massacre was a massacre of striking miners by Bolivian government forces at the Catavi mine on 21 December 1942. According to the official report, 19 miners were killed and 400 wounded, while estimates by the workers themselves reported up to 400 deaths.', 1942, 12, 21, NULL, NULL, NULL, 'day', '21 December 1942', 37, 'https://en.wikipedia.org/wiki/Catavi_massacre'),
  ('Q4414118', 'Bolivian National Revolution (1952-1964)', 'The Bolivian Revolution of 1952 (Spanish: Revolución boliviana), also known as the Revolution of ''52, was a series of political demonstrations led by the Revolutionary Nationalist Movement (MNR), which, in alliance with the liberals and the communists, sought to overthrow the ruling Bolivian oligarchy and implement a new socioeconomic model in Bolivia. Its main leaders were the former presidents Víctor Paz Estenssoro and Hernán Siles Zuazo.', 1952, 4, 11, NULL, NULL, NULL, 'day', '11 April 1952', 47, 'https://en.wikipedia.org/wiki/Bolivian_National_Revolution'),
  ('Q28454110', '1964 Bolivian coup d''état', '1964 Bolivian coup d''état in Bolivia was a coup under the leadership of Vice-president René Barrientos and Bolivian Army commander-in-chief Alfredo Ovando Candía against the President Víctor Paz Estenssoro, leader of the Bolivian National Revolution of 1952, who recently had been re-elected for his third term in office. There are those who label the November 4th coup as a counterrevolution.', 1964, 11, 4, NULL, NULL, NULL, 'day', '4 November 1964', 34, 'https://en.wikipedia.org/wiki/1964_Bolivian_coup_d''%C3%A9tat'),
  ('Q123529158', '1969 Bolivian coup d''état', '1969 Bolivian coup d''état (also known as the 26 September Revolution by supporters) was a military coup carried out by the Bolivian commander Alfredo Ovando Candía that deposed President Luís Adolfo Siles Salinas, former vice-president of René Barrientos who had taken office after his death. Ovando seized power in the name of a "nationalist and revolutionary" program formulated in the Revolutionary Mandate of the Armed Forces.', 1969, 9, 26, NULL, NULL, NULL, 'day', '26 September 1969', 30, 'https://en.wikipedia.org/wiki/1969_Bolivian_coup_d''%C3%A9tat'),
  ('Q116880048', '1971 Bolivian coup d''état', 'The 1971 Bolivian coup d''état was led by military officer Hugo Banzer on August 18, 1971, against the government of president Juan José Torres.', 1971, 8, 18, NULL, NULL, NULL, 'day', '18 August 1971', 30, 'https://en.wikipedia.org/wiki/1971_Bolivian_coup_d''%C3%A9tat'),
  ('Q5657104', 'Charaña Accords', 'The Charaña Accord, also known as the Hug of Charaña or the Act of Charaña, is the name given to an unrealized treaty that was discussed between the dictators of Bolivia and Chile, Hugo Banzer and Augusto Pinochet respectively. These discussions took place mostly on the Bolivian train station of Charaña on February 8, 1975, and included the brief reestablishment of diplomatic relations between the two nations which had been severed on 1962 because of the Atacama border dispute which was to be solved via a Chilean proposal for the exchange of territories between Bolivia and Chile, with the…', 1975, 2, 8, NULL, NULL, NULL, 'day', '8 February 1975', 30, 'https://en.wikipedia.org/wiki/Chara%C3%B1a_Accord'),
  ('Q129259431', 'July 1978 Bolivian coup d''état', 'The July 1978 Bolivian coup d''état was the military takeover of the Bolivian government by General Pereda and his supporters at the expense of the Banzer regime. The Junta of Commanders that seized power in the coup promptly installed General Pereda as President of Bolivia on July 21, 1978.', 1978, 7, 21, NULL, NULL, NULL, 'day', '21 July 1978', 26, 'https://en.wikipedia.org/wiki/July_1978_Bolivian_coup_d''%C3%A9tat'),
  ('Q4729364', 'All Saints'' Massacre', 'The All Saints'' massacre (Spanish: Masacre de Todos Santos) is the name given to the violent crackdown against popular protests by the military regime of Alberto Natusch Busch that seized power in a coup on November 1 (All Saints'' Day), 1979. In response to the November 1 coup, the Central Obrera Boliviana (COB) trade union confederation launched a campaign of mass protests, which the military violently suppressed.', 1979, 11, 1, NULL, NULL, NULL, 'day', '1 November 1979', 34, 'https://en.wikipedia.org/wiki/All_Saints''_Massacre'),
  ('Q3562643', 'Eastern Air Lines Flight 980', 'Eastern Air Lines Flight 980 was a scheduled international flight from Asunción, Paraguay, to Miami, Florida, United States. On January 1, 1985, while descending towards La Paz, Bolivia, for a scheduled stopover, the Boeing 727 jetliner struck Mount Illimani at an altitude of 19,600 feet (6,000 m), killing all 29 people on board.', 1985, 1, 1, NULL, NULL, NULL, 'day', '1 January 1985', 51, 'https://en.wikipedia.org/wiki/Eastern_Air_Lines_Flight_980'),
  ('Q5943238', '1998 Aiquile earthquake', 'The 1998 Aiquile earthquake occurred on May 22 at 00:48:53 local time in Bolivia. This strike-slip earthquake had a moment magnitude of 6.6 and a maximum Mercalli intensity of VIII (Severe).', 1998, 5, 22, NULL, NULL, NULL, 'day', '22 May 1998', 34, 'https://en.wikipedia.org/wiki/1998_Aiquile_earthquake'),
  ('Q1877202', 'Bolivian gas conflict', 'The Bolivian Gas War (Spanish: Guerra del Gas) or Bolivian gas conflict was a social confrontation in Bolivia reaching its peak in 2003, centering on the exploitation of the country''s vast natural gas reserves. The expression can be extended to refer to the general conflict in Bolivia over the exploitation of gas resources, thus including the 2005 protests and the election of Evo Morales as president.', 2003, 10, 17, 2006, NULL, NULL, 'day', '17 October 2003 – 2006', 47, 'https://en.wikipedia.org/wiki/Bolivian_gas_war'),
  ('Q16004619', '2014 Iquique earthquake', 'The 2014 Iquique earthquake struck off the coast of Chile on 1 April, with a moment magnitude of 8.1–8.2, at 20:46 local time (23:46 UTC). The epicenter of the earthquake was approximately 95 kilometres (59 mi) northwest of Iquique.', 2014, 4, 1, NULL, NULL, NULL, 'day', '1 April 2014', 57, 'https://en.wikipedia.org/wiki/2014_Iquique_earthquake'),
  ('Q71936844', '2019 Bolivian protests', 'The 2019 Bolivian protests, also known as the Pitita Revolution (Spanish: la Revolución de las Pititas), were protests and marches from 21 October 2019 until late November of that year in Bolivia, in response to claims of electoral fraud in the 2019 general election of 20 October. After 11 November 2019, there were protests by supporters of the outgoing government in response to Jeanine Áñez becoming the acting president of Bolivia.', 2019, 10, NULL, 2019, 11, NULL, 'month', 'October 2019 – November 2019', 56, 'https://en.wikipedia.org/wiki/2019_Bolivian_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q139807452', '2026 Bolivian protests', 'The 2026 Bolivian protests were a series of mass protests that occurred in Bolivia in May and June, involving widespread demonstrations, blockades, and strikes in multiple regions across Bolivia that targeted major cities. They were led and participated predominantly by indigenous groups.', 2026, 5, NULL, NULL, NULL, NULL, 'month', 'May 2026', 50, 'https://en.wikipedia.org/wiki/2026_Bolivian_protests');
